using System.Reflection;
using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private const string Domain = "PaymentAuthorization.Domain";
    private const string Application = "PaymentAuthorization.Application";
    private const string Infrastructure = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Text.Json",
        "Microsoft.Data", "Microsoft.EntityFrameworkCore", "Microsoft.Extensions.Http",
    ];

    private static Assembly Load(string name) => Assembly.Load(name);

    [Fact]
    public void Domain_depends_on_no_other_layer()
        => AssertNone(Types.InAssembly(Load(Domain)), [Application, Infrastructure]);

    [Fact]
    public void Application_does_not_depend_on_Infrastructure()
        => AssertNone(Types.InAssembly(Load(Application)), [Infrastructure]);

    [Fact]
    public void Domain_and_Application_avoid_technical_namespaces()
    {
        AssertNone(Types.InAssembly(Load(Domain)), TechnicalNamespaces);
        AssertNone(Types.InAssembly(Load(Application)), TechnicalNamespaces);
    }

    private static void AssertNone(Types types, string[] forbidden)
    {
        var result = types.ShouldNot().HaveDependencyOnAny(forbidden).GetResult();
        Assert.True(result.IsSuccessful,
            "Forbidden dependencies in: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
